// lazytopper/src/data/bankFix/pyqRestore1Ledger.ts
//
// PYQ-RESTORE-1 (2026-10-18) - the provenance ledger for restoring CBSE board-paper years.
//
// OWNER RULINGS (18 Oct 2026):
//   (a) amends BANK-FIX-1 ruling 2. A PYQ row whose QUESTION matches the official CBSE paper after
//       removing only extraction garble (stray mark digits, page numbers, broken glyphs, header
//       residue), and whose year and set are confirmed from the official paper, gets `pyqYear` /
//       `pyqSet` restored and `sourceOverride: "others"` removed. A corrected / completed SOLUTION
//       does not change the question's provenance. A row whose question text had to be changed in
//       substance stays "others".
//   (b) Section D (5-mark) board questions are allowed in "Try a board question" (PR-3).
//
// METHOD (Maths, PR-1). Every one of the 136 served Maths `PYQ-M-*` rows filed under Others was
// located in the official CBSE question paper named by its `ncertRef` (set code 30/x/x = Mathematics
// Standard 041; 30(B) = the paper for visually impaired candidates) for the year of its source file,
// using the official zips from cbse.gov.in (URL + SHA-256 of each inner PDF below). The stem was
// compared word-for-word with the paper's text layer AND with a render of the page (the text layer
// drops minus signs, θ and √, which are drawn as vectors). The year and set are the values the row
// carried before BANK-FIX-1 (git 2ce40687^), and each was confirmed against the paper.
//   verdict "restored"    - question matches; pyqYear / pyqSet restored, override removed.
//                           `stemReset`: the bank's stem had editorial drift (articles, "mid-point",
//                           a bank-added "(Use π = 22/7)", the paper's mark digits) and was reset to
//                           the official wording. `optionsReset`: the bank's MCQ distractors differed
//                           from the paper and were reset to the official options (key unchanged).
//   verdict "kept-others" - the question had been changed in substance (a figure-bound question
//                           rewritten in words, data added from a figure, a resolved ambiguity) or
//                           the claimed reference could not be confirmed; the row stays Others.
//   verdict "labelled"    - an already-yeared PYQ row whose steps gained "[N mark]" prefixes.
// STEP MARKS. For a restored or already-yeared row whose solutionSteps lacked "[N mark]" prefixes,
// the prefixes come from the OFFICIAL marking scheme of the same paper (`ms`), rendered and read
// per question; marks sum to the row's `marks`; steps were split / merged only to match the scheme
// (`stepsRecut`; where a bank step had lost superscripts or glyphs they were restored). Objective
// items (Section A) carry one "[1 mark]" step: CBSE awards the mark for the correct option only.
// Not labelled (listed in the PR): OR rows that hold both alternatives in one row, and rows whose
// existing steps are garbled or truncated (they need a solution rewrite, not a label).
// Row ids are never changed (Mistake Intelligence history keys on them).

export interface PyqRestore1Entry {
  id: string;
  verdict: "restored" | "kept-others" | "labelled";
  /** The row's paper reference (its `ncertRef`). */
  ref: string;
  year: string;
  set: string;
  /** Official question paper: zip URL#inner path, and the SHA-256 of that inner PDF. */
  qp: string;
  qpSha256: string;
  /** Official marking scheme for the same paper. */
  ms: string;
  msSha256: string;
  stemReset?: true;
  optionsReset?: true;
  /** Present when this lane added "[N mark]" prefixes: the marks, in step order. */
  stepMarks?: readonly number[];
  stepsRecut?: true;
  scheme?: string;
  why: string;
}

